import{_ as t,o,c as s,a2 as n}from"./chunks/framework.ChIlRNAd.js";const p=JSON.parse('{"title":"Notifications et webhooks","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/notifications.md","filePath":"fr/guide/notifications.md"}'),r={name:"fr/guide/notifications.md"};function i(a,e,d,l,c,h){return o(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="notifications-et-webhooks" tabindex="-1">Notifications et webhooks <a class="header-anchor" href="#notifications-et-webhooks" aria-label="Permalink to &quot;Notifications et webhooks&quot;">​</a></h1><p>Nid vous prévient des événements importants de trois façons : la <strong>cloche</strong> de l&#39;en-tête, des <strong>toasts</strong> (messages temporaires à l&#39;écran) et des <strong>webhooks</strong> vers vos services. Les réglages sont dans <strong>Paramètres › Notifications &amp; webhooks</strong>.</p><hr><h2 id="cloche-de-notifications" tabindex="-1">Cloche de notifications <a class="header-anchor" href="#cloche-de-notifications" aria-label="Permalink to &quot;Cloche de notifications&quot;">​</a></h2><p>La cloche, en haut à droite de chaque page, affiche le nombre de notifications non lues. Elle ouvre un panneau avec les dernières notifications :</p><ul><li>cliquer une notification la marque comme lue ;</li><li><strong>Tout marquer lu</strong> ;</li><li><strong>Supprimer lues</strong> : après confirmation, supprime définitivement les notifications lues ;</li><li>le bouton de suppression d&#39;une ligne supprime cette notification.</li></ul><hr><h2 id="preferences-de-notification" tabindex="-1">Préférences de notification <a class="header-anchor" href="#preferences-de-notification" aria-label="Permalink to &quot;Préférences de notification&quot;">​</a></h2><p>Dans <strong>Paramètres › Notifications &amp; webhooks</strong>, chaque événement a deux interrupteurs : <strong>In-app</strong> (dans la cloche) et <strong>Toast</strong> (message temporaire à l&#39;écran). Chaque changement est enregistré immédiatement.</p><table tabindex="0"><thead><tr><th>Événement</th><th>Quand</th></tr></thead><tbody><tr><td><strong>Rapport hebdomadaire</strong></td><td>résumé d&#39;activité chaque lundi</td></tr><tr><td><strong>Tâche terminée</strong></td><td>une tâche (action de masse, sauvegarde, règle) se termine</td></tr><tr><td><strong>Tâche en échec</strong></td><td>une tâche échoue</td></tr><tr><td><strong>Règle exécutée</strong></td><td>une règle automatique s&#39;exécute</td></tr><tr><td><strong>Alerte de stockage</strong></td><td>le stockage des archives approche sa limite</td></tr><tr><td><strong>Alerte d&#39;intégrité</strong></td><td>un problème est détecté dans les archives</td></tr></tbody></table><hr><h2 id="webhooks" tabindex="-1">Webhooks <a class="header-anchor" href="#webhooks" aria-label="Permalink to &quot;Webhooks&quot;">​</a></h2><p>« Envoie les événements vers Discord, Slack, ntfy ou une URL à vous (signée HMAC). »</p><h3 id="creer-un-webhook" tabindex="-1">Créer un webhook <a class="header-anchor" href="#creer-un-webhook" aria-label="Permalink to &quot;Créer un webhook&quot;">​</a></h3><p><strong>Nouveau webhook</strong> ouvre le formulaire :</p><ul><li><strong>Nom</strong> ;</li><li><strong>URL</strong> ;</li><li><strong>Type</strong> : <strong>Générique (HMAC)</strong>, <strong>Discord</strong>, <strong>Slack</strong>, <strong>ntfy</strong> ;</li><li>pour ntfy : <strong>Utilisateur ntfy (facultatif)</strong> et <strong>Mot de passe ntfy (facultatif)</strong> ;</li><li><strong>Événements</strong> (au moins un) :</li></ul><table tabindex="0"><thead><tr><th>Événement</th><th>Préférence correspondante</th></tr></thead><tbody><tr><td><code>job.completed</code></td><td>Tâche terminée</td></tr><tr><td><code>job.failed</code></td><td>Tâche en échec</td></tr><tr><td><code>rule.executed</code></td><td>Règle exécutée</td></tr><tr><td><code>quota.warning</code></td><td>Alerte de stockage</td></tr><tr><td><code>integrity.failed</code></td><td>Alerte d&#39;intégrité</td></tr></tbody></table><p>Le rapport hebdomadaire n&#39;est pas envoyé par webhook.</p><h3 id="gerer-les-webhooks" tabindex="-1">Gérer les webhooks <a class="header-anchor" href="#gerer-les-webhooks" aria-label="Permalink to &quot;Gérer les webhooks&quot;">​</a></h3><p>Chaque webhook de la liste affiche son type et le code du dernier envoi (« dernier envoi : 200 »). Un interrupteur l&#39;active ou le désactive sans le supprimer. Son menu propose <strong>Envoyer un test</strong> et <strong>Supprimer</strong> (après confirmation).</p><h3 id="signature-type-generique" tabindex="-1">Signature (type Générique) <a class="header-anchor" href="#signature-type-generique" aria-label="Permalink to &quot;Signature (type Générique)&quot;">​</a></h3><p>Les webhooks de type <strong>Générique (HMAC)</strong> ajoutent un en-tête <code>X-Webhook-Signature: sha256=…</code>, HMAC-SHA256 du corps de la requête. Votre serveur peut le vérifier pour s&#39;assurer que la requête vient bien de Nid.</p><hr><h2 id="exemples" tabindex="-1">Exemples <a class="header-anchor" href="#exemples" aria-label="Permalink to &quot;Exemples&quot;">​</a></h2><h3 id="discord" tabindex="-1">Discord <a class="header-anchor" href="#discord" aria-label="Permalink to &quot;Discord&quot;">​</a></h3><ol><li>Dans Discord : <strong>Paramètres du salon</strong> → <strong>Intégrations</strong> → <strong>Webhooks</strong> → <strong>Nouveau webhook</strong>, puis copiez l&#39;URL</li><li>Dans Nid, créez un webhook de type <strong>Discord</strong> avec cette URL et choisissez les événements</li></ol><h3 id="ntfy" tabindex="-1">ntfy <a class="header-anchor" href="#ntfy" aria-label="Permalink to &quot;ntfy&quot;">​</a></h3><p><a href="https://ntfy.sh" target="_blank" rel="noreferrer">ntfy</a> envoie des notifications push sur votre téléphone ou navigateur.</p><ul><li><strong>Topic public</strong> : créez un webhook de type <strong>ntfy</strong> avec l&#39;URL <code>https://ntfy.sh/nid-alerts</code>, puis abonnez-vous au même topic dans l&#39;app ntfy.</li><li><strong>Topic protégé</strong> (serveur ntfy auto-hébergé, par exemple) : renseignez l&#39;URL de votre serveur (<code>https://ntfy.example.com/mon-topic</code>) et les champs utilisateur / mot de passe ; ils sont envoyés en <code>Authorization: Basic</code>. <strong>Envoyer un test</strong> vérifie l&#39;authentification.</li></ul><div class="tip custom-block"><p class="custom-block-title">Serveur ntfy auto-hébergé</p><p>Avec un contrôle d&#39;accès (<code>auth-default-access: deny-all</code>), créez un utilisateur et autorisez-le en écriture sur le topic :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ntfy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> monuser</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ntfy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> access</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> monuser</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mon-topic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> write</span></span></code></pre></div></div><div class="warning custom-block"><p class="custom-block-title">Sécurité</p><p>Les identifiants ntfy sont stockés en clair dans la base de données. Utilisez un compte dédié avec des permissions minimales (écriture seule sur le topic concerné).</p></div>`,31)])])}const g=t(r,[["render",i]]);export{p as __pageData,g as default};
